<template><section class="page"><header><div><h1 class="page-title">AI 工具集管理</h1><p class="page-description">管理 App 中部固定展示的 6 个智能体入口。</p></div><span>{{visible.length}} / 6 个</span></header><div class="tools"><el-input v-model="keyword" clearable prefix-icon="el-icon-search" placeholder="搜索工具名称或 ID"/><el-radio-group v-model="status"><el-radio-button label="ON">使用中</el-radio-button><el-radio-button label="OFF">已停用</el-radio-button><el-radio-button label="ALL">全部</el-radio-button></el-radio-group></div><div class="list"><article v-for="item in visible" :key="item.id"><div class="icon">{{item.name[0]}}</div><div class="info"><strong>{{item.name}}</strong><span>工具 ID {{item.id}} · 排序 {{item.order}}</span><p>{{item.desc}}</p></div><el-tag :type="item.status==='ON'?'success':'info'">{{item.status==='ON'?'启用':'已停用'}}</el-tag><div class="actions"><el-button type="text" @click="edit(item)">编辑</el-button><el-button type="text" @click="toggle(item)">{{item.status==='ON'?'停用':'启用'}}</el-button><el-button type="text" @click="manage(item)">运营配置</el-button></div></article></div><el-dialog :title="dialogTitle" :visible.sync="dialog" width="640px"><template v-if="panel==='edit'"><el-form label-width="100px"><el-form-item label="名称"><el-input v-model="draft.name"/></el-form-item><el-form-item label="简介"><el-input v-model="draft.desc" type="textarea"/></el-form-item><el-form-item label="展示顺序"><el-input-number v-model="draft.order" :min="0" :max="5"/></el-form-item><el-form-item label="免费次数"><el-input-number v-model="draft.free" :min="0"/></el-form-item></el-form></template><template v-else><div class="config"><button @click="panel='questions'"><strong>问题管理</strong><span>App 直接展示的推荐提问</span></button><button @click="panel='marketing'"><strong>营销管理</strong><span>免费、会员、分享、白名单权益</span></button><button disabled><strong>推荐管理</strong><span>暂未关联商品</span></button></div><div v-if="panel==='questions'" class="sub"><div v-for="(q,i) in questions" :key="q"><span>{{i+1}}. {{q}}</span><el-button type="text" @click="questions.splice(i,1)">删除</el-button></div><el-input v-model="newQuestion" placeholder="新增推荐提问"><el-button slot="append" @click="addQuestion">添加</el-button></el-input></div><div v-if="panel==='marketing'" class="sub"><el-radio-group v-model="marketing"><el-radio label="免费"/><el-radio label="会员"/><el-radio label="分享"/><el-radio label="白名单"/></el-radio-group><el-date-picker v-model="marketingPeriod" type="daterange" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期"/></div></template><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></span></el-dialog></section></template>
<script>export default{data:()=>({keyword:'',status:'ON',dialog:false,panel:'edit',current:null,draft:{},newQuestion:'',questions:['拍道题，帮我解','帮我分析这道题','帮我看看这个病理图','这道笔试题怎么做？'],marketing:'免费',marketingPeriod:[],rows:[['医学知识问答','面向医学知识场景的智能问答入口'],['拍照解题','拍摄医学试题后识别并辅助解析'],['技能手册','查看缝合、穿刺、急救等技能内容'],['写简历','辅助整理医学岗位求职简历'],['找工作','匹配医学岗位与招聘信息'],['调剂查询','查询医学考研调剂相关信息']].map((x,i)=>({id:[25,24,20,18,23,19][i],order:i,name:x[0],desc:x[1],free:3,status:'ON'}))}),computed:{visible(){const q=this.keyword.toLowerCase();return this.rows.filter(x=>(this.status==='ALL'||x.status===this.status)&&(!q||(x.name+x.id).toLowerCase().includes(q)))},dialogTitle(){return this.panel==='edit'?'编辑 AI 工具':(this.current?this.current.name:'')+' · 运营配置'}},methods:{edit(x){this.current=x;this.draft={...x};this.panel='edit';this.dialog=true},manage(x){this.current=x;this.panel='manage';this.dialog=true},toggle(x){x.status=x.status==='ON'?'OFF':'ON';this.$message.success('状态已更新')},addQuestion(){if(!this.newQuestion.trim())return;this.questions.push(this.newQuestion.trim());this.newQuestion=''},save(){if(this.panel==='edit'){const clash=this.rows.find(x=>x!==this.current&&x.order===this.draft.order);if(clash)return this.$message.warning('该排序已被占用');Object.assign(this.current,this.draft)}this.dialog=false;this.$message.success('配置已保存')}}}</script>
<style scoped>.page{max-width:1280px;margin:auto}.page>header,.tools{display:flex;align-items:flex-end;justify-content:space-between}.page>header>span{color:var(--muted)}.tools{justify-content:flex-start;gap:12px;margin:24px 0}.tools .el-input{width:320px}.list{display:grid;grid-template-columns:repeat(2,minmax(360px,1fr));gap:12px}.list article{display:grid;grid-template-columns:48px 1fr auto;gap:12px;padding:18px;background:#fff;border-radius:10px}.icon{width:46px;height:46px;display:grid;place-items:center;border-radius:9px;color:#a90a13;background:#fff1f2;font-size:18px;font-weight:800}.info strong,.info span{display:block}.info span{color:var(--muted);font-size:12px}.info p{margin:12px 0;color:#596271}.actions{grid-column:2/4}.config{display:grid;gap:10px}.config button{padding:15px;border:1px solid var(--line);border-radius:8px;background:#fff;text-align:left}.config strong,.config span{display:block}.config span{margin-top:4px;color:var(--muted)}.sub{display:grid;gap:10px;margin-top:16px}.sub>div{display:flex;justify-content:space-between;align-items:center;padding:9px 12px;background:#f7f8fa}</style>
